 const loadXlsx=()=>new Promise((resolve,reject)=>{if(window.XLSX)return resolve();const script=document.createElement('script');script.src='/xlsx.full.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Không tải được bộ đọc Excel.'));document.body.append(script);});
 const readFileDataUrl=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Không đọc được file.'));reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file);});
 const compressReceiptImage=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('Không đọc được ảnh.'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(Error('Ảnh không hợp lệ.'));img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.68));};img.src=reader.result;};reader.readAsDataURL(file);});
 const close=()=>{if(!busy)closeModal('incomingStock');};
