 const updatePdfButton=()=>{$('#incomingPdf').disabled=!selectedShipment||busy;$('#incomingPdf').title=selectedShipment?'Xuất phiếu hàng sắp về đang chọn':'Chọn phiếu chờ về để xuất PDF';};
