 const normalize=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9]/gi,'').toLowerCase();
 const loadScript=(src,globalName)=>new Promise((resolve,reject)=>{if(globalThis[globalName])return resolve(globalThis[globalName]);const script=document.createElement('script');script.src=src;script.async=true;script.onload=()=>globalThis[globalName]?resolve(globalThis[globalName]):reject(Error('Không tải được bộ đọc phiếu.'));script.onerror=()=>reject(Error('Không tải được bộ đọc phiếu. Kiểm tra kết nối mạng rồi thử lại.'));document.head.append(script);});
 async function scanSource(file){
  if(!file)return;
  if(file.size>25000000)throw Error('Chọn ảnh hoặc PDF dưới 25 MB.');
  const Tesseract=await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js','Tesseract');let source=file;
  if(file.type==='application/pdf'||/\.pdf$/i.test(file.name)){const pdfjs=await loadScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js','pdfjsLib');pdfjs.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';const pdf=await pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise,page=await pdf.getPage(1),viewport=page.getViewport({scale:2}),canvas=document.createElement('canvas');canvas.width=Math.ceil(viewport.width);canvas.height=Math.ceil(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;source=canvas.toDataURL('image/jpeg',.92);}
  const worker=await Tesseract.createWorker('eng');try{
   await worker.setParameters({tessedit_pageseg_mode:'6',preserve_interword_spaces:'1'});const tableText=(await worker.recognize(source)).data.text||'';
   // Sparse text catches cells that a table pass separates onto their own line.
   await worker.setParameters({tessedit_pageseg_mode:'11',preserve_interword_spaces:'1'});const sparseText=(await worker.recognize(source)).data.text||'';
   return `${tableText}\n${sparseText}`;
  }finally{await worker.terminate();}
 }
 const parseScannedReceipt=(text,products)=>{
  const productBySku=new Map(products.map(product=>[String(product.sku).trim().toUpperCase(),product])),known=[...productBySku.keys()],found=new Map(),lines=String(text||'').split(/\r?\n/).map(line=>line.replace(/\s+/g,' ').trim()).filter(Boolean);
  const distance=(a,b)=>{const row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let prev=row[0];row[0]=i;for(let j=1;j<=b.length;j++){const next=Math.min(row[j]+1,row[j-1]+1,prev+(a[i-1]===b[j-1]?0:1));prev=row[j];row[j]=next;}}return row[b.length];};
  const resolveSku=token=>{if(productBySku.has(token))return token;if(token.length<6)return '';const ranked=known.map(sku=>({sku,score:1-distance(token,sku)/Math.max(token.length,sku.length)})).sort((a,b)=>b.score-a.score);return ranked[0]?.score>=.84&&ranked[0].score-(ranked[1]?.score||0)>=.08?ranked[0].sku:'';};
  const quantityFromLine=line=>line.match(/(?:TRG|TRANG)\s*[|:/-]?\s*(\d{1,9})/i)?.[1]
   ||line.match(/\b(\d{2,9})\b(?=\s*(?:(?:[|/\\-]\s*)?(?:L[1I]|LI)\b|[|/\\-]\s*1\b))/i)?.[1]
   ||line.match(/^\D*(\d{2,9})\D*$/)?.[1];
  for(let index=0;index<lines.length;index++){
   const line=lines[index],tokens=line.toUpperCase().match(/[A-Z0-9]{6,18}/g)||[],sku=tokens.map(resolveSku).find(Boolean);if(!sku||found.has(sku))continue;
   for(const candidate of lines.slice(index,index+7)){
    if(candidate!==line&&(candidate.toUpperCase().match(/[A-Z0-9]{6,18}/g)||[]).map(resolveSku).find(Boolean))break;
   const qty=quantityFromLine(candidate);if(qty){found.set(sku,Number(qty));break;}
   }
  }
  return found;
 };
 function applyScannedReceipt(text,fileName){
  const found=parseScannedReceipt(text,catalog);
  if(!found.size)throw Error('Không nhận được SKU khớp chính xác trong danh mục. Hãy chụp rõ phần bảng Mã số và SL giao, hoặc dùng file Excel.');
  const ticket=String(text).match(/S[OỐ]\s*(?:PXK|PHIẾU(?:\s*XUẤT)?)[^A-Z0-9]{0,12}([A-Z0-9][A-Z0-9._/-]{3,})/i)?.[1]?.replace(/[._]/g,'-')||'',date=String(text).match(/NG[ÀA]Y\s*(?:GIAO|ĐẶT)[^0-9]{0,15}(\d{1,2}[/-]\d{1,2}[/-]\d{2,4})/i)?.[1];
  if(ticket)$('#incomingTicket').value=ticket;if(date){const [day,month,year]=date.split(/[/-]/);$('#incomingDate').value=`${year.length===2?'20'+year:year}-${month.padStart(2,'0')}-${day.padStart(2,'0')}`;}
  rows=[['MÃ HÀNG','SỐ LƯỢNG'],...[...found].map(([sku,quantity])=>[sku,quantity])];workbook=null;$('#incomingSheetField').hidden=true;$('#incomingHeader').value=1;mapping();$('#incomingReview').disabled=false;previewPayload=null;$('#incomingStatus').textContent=`Đã đọc ${found.size.toLocaleString('vi-VN')} SKU từ ${fileName}. Kiểm tra phiếu, kho nhận và bấm Xem trước trước khi lưu.`;
 }
 async function previewScannedReceipt(fileName){
  const arrivalDate=$('#incomingDate').value,ticketNumber=$('#incomingTicket').value.trim();
  if(!ticketNumber)throw Error('Không nhận được số phiếu. Nhập số phiếu trước khi xem trước.');
  if(!arrivalDate)throw Error('Không nhận được ngày giao. Chọn ngày về hàng trước khi xem trước.');
  const values=rows.slice(1).map(row=>({sku:String(row[0]||'').trim(),quantity:Number(row[1])})).filter(row=>row.sku&&Number.isFinite(row.quantity)&&row.quantity>=0);
  const payload={rows:values,ticketNumber,warehouse:$('#incomingWarehouse').value,arrivalDate,filename:fileName||'Phieu-giao-hang-OCR'};
  const result=await BN.api('/incoming-stock/preview','POST',payload);previewPayload=payload;
  $('#incomingStatus').textContent=`Đã đọc và đối chiếu ${result.matched.toLocaleString('vi-VN')} SKU · ${result.quantity.toLocaleString('vi-VN')} sản phẩm · ${number(result.cartons)} thùng · ${number(result.weightKg)} kg · ${number(result.volumeM3)} m³. Kiểm tra lại trước khi lưu.`;
  $('#incomingPreview').innerHTML=`<p><b>Đối chiếu từ phiếu đã quét:</b></p><div style="overflow:auto"><table style="min-width:680px"><thead><tr><th>SKU</th><th>Sản phẩm</th><th>SL</th><th>Thùng</th><th>Kg</th><th>m³</th></tr></thead><tbody>${result.samples.map(item=>`<tr><td>${esc(item.sku)}</td><td>${esc(item.name)}</td><td>${number(item.quantity)}</td><td>${item.cartons??'—'}</td><td>${item.weightKg===null?'—':number(item.weightKg)}</td><td>${item.volumeM3===null?'—':number(item.volumeM3)}</td></tr>`).join('')}</tbody></table></div>${result.unknown.length?`<details><summary>SKU không tìm thấy</summary><p>${result.unknown.map(esc).join(', ')}</p></details>`:''}`;
 }
 async function readReceiptFile(file){if(busy)return;lock(true);try{const text=await scanSource(file);applyScannedReceipt(text,file.name);await previewScannedReceipt(file.name);}catch(error){$('#incomingStatus').textContent=error.message;}finally{lock(false);}}
 const activeWarehouses=()=>catalogMeta.warehouses.filter(name=>!['NCC','Hàng chờ về'].includes(name));
 const setIncomingStockBadge=count=>{pendingIncomingStock=Math.max(0,Number(count)||0);document.querySelectorAll('#openIncomingStock,#mobileIncomingStock').forEach(button=>{let badge=button.querySelector('.incoming-stock-badge');if(!badge){badge=document.createElement('b');badge.className='incoming-stock-badge';button.append(badge);}badge.hidden=!pendingIncomingStock;badge.textContent=pendingIncomingStock>99?'99+':String(pendingIncomingStock);badge.setAttribute('aria-label',`${pendingIncomingStock} phiếu hàng sắp về`);button.setAttribute('aria-label',pendingIncomingStock?`Hàng sắp về, ${pendingIncomingStock} phiếu`:'Hàng sắp về');});};
