  supplierOrderModal.innerHTML=`<div class="modal-backdrop" data-supplier-order-close></div><div class="dialog product-editor" role="dialog" aria-modal="true" aria-labelledby="supplierOrderTitle"><div class="dialog-head"><div><p class="eyebrow">ĐẶT HÀNG NCC</p><h2 id="supplierOrderTitle">Tạo phiếu đặt hàng nhanh</h2></div><button class="icon-btn" data-supplier-order-close aria-label="Đóng">×</button></div><p class="search-help">Nhân viên lập phiếu để Manager phê duyệt. Hàng chỉ được cộng vào kho Hàng chờ về sau khi phê duyệt.</p><form id="supplierOrderForm"><div class="product-form-grid"><label>Số phiếu đặt hàng<input name="ticketNumber" required maxlength="100" value="${esc(supplierOrderNumber(items.some(item=>Number(item.printFee)>0)))}"></label><label>Số báo giá<input name="quoteNumber" required maxlength="100" value="${esc(document.querySelector('#quoteNo')?.value||'')}"></label><label>Số đơn hàng nội bộ NCC<input name="supplierInternalOrderNumber" maxlength="100" placeholder="Ví dụ: PO nội bộ NCC"></label><label>Nhà cung cấp (NCC)<select name="supplierName" required disabled><option>Đang tải danh sách NCC từ Sapo…</option></select></label><label>Kho nhận<select name="warehouse">${activeWarehouses().map(name=>`<option value="${esc(name)}" ${name===defaultWarehouse?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Ngày hẹn giao<input name="arrivalDate" type="date" required value="${new Date().toISOString().slice(0,10)}"></label><label>Tỷ lệ đặt cọc<select name="depositRate">${supplierDepositOptions()}</select></label></div><div class="supplier-order-items"><div class="supplier-order-head"><b>Danh sách hàng đặt</b><button class="btn soft" type="button" id="supplierOrderAdd">+ Thêm mã</button></div><div style="overflow:auto"><table><thead><tr><th>SKU</th><th>Sản phẩm</th><th>SL</th><th>Giá sau CK</th><th>Thành tiền</th><th>Ảnh/thiết kế</th><th></th></tr></thead><tbody id="supplierOrderRows"></tbody></table></div><div class="supplier-order-totals"><span>Tạm tính <b id="supplierOrderSubtotal">0 đ</b></span><span>VAT <b id="supplierOrderVat">0 đ</b></span><strong>Tổng thanh toán <b id="supplierOrderTotal">0 đ</b></strong></div></div><p id="supplierOrderStatus" role="status"></p><div class="dialog-actions"><button class="btn ghost" type="button" data-supplier-order-close>Hủy</button>${canManage?'<button class="btn soft" type="button" id="supplierOrderReview">Đơn chờ duyệt <b class="supplier-order-badge" hidden aria-label="0 đơn chờ duyệt">0</b></button>':''}<button class="btn soft" type="button" id="supplierOrderPdf">Xuất PDF</button><button class="btn primary" type="submit">Đặt hàng chờ phê duyệt</button></div></form></div>`;
  dockSupplierFormActions(supplierOrderModal);
  setSupplierOrderBadge(pendingSupplierOrders);
