 function openSapoGoodsReceipt(shipment){const items=shipment.rows.map(row=>{const product=catalog.find(item=>String(item.sku).toLowerCase()===String(row.sku).toLowerCase());return {sku:row.sku,name:row.name,quantity:Number(row.quantity)||0,unit:product?.unit||''};}).filter(row=>row.sku&&row.quantity>0),total=items.reduce((sum,row)=>sum+row.quantity,0);receiptModal.innerHTML=`<div class="modal-backdrop" data-receipt-close></div><div class="dialog product-editor sapo-receipt-dialog" role="dialog" aria-modal="true" aria-labelledby="sapoReceiptTitle"><div class="dialog-head"><div><p class="eyebrow">NHẬP HÀNG SAPO</p><h2 id="sapoReceiptTitle">Tạo đơn nhập Sapo</h2></div><button class="icon-btn" data-receipt-close aria-label="Đóng">×</button></div><p class="search-help">Kiểm tra thông tin trước khi tạo phiếu. Giá nhập tạm thời được gửi là <b>0 đ</b> cho mọi sản phẩm.</p><form id="sapoReceiptForm"><div class="product-form-grid"><label>Mã phiếu nhập<input name="ticketNumber" required maxlength="100" value="${esc(shipment.ticketNumber)}"></label><label>Nhà cung cấp (NCC)<input name="supplierName" required maxlength="300" placeholder="Nhập tên nhà cung cấp"></label><label>Kho nhận<select name="warehouseName">${activeWarehouses().map(name=>`<option ${name===shipment.warehouse?'selected':''}>${esc(name)}</option>`).join('')}</select></label><label>Nhân viên tạo<input name="employeeName" readonly value="${esc(BN.user.name)}"></label><label>Ngày nhập<input name="receiptDate" type="date" required value="${esc(shipment.arrivalDate)}"></label><label>Tổng số lượng nhập<input readonly value="${number(total)}"></label></div><div class="sapo-receipt-items"><b>${items.length.toLocaleString('vi-VN')} mã hàng · ${number(total)} sản phẩm · giá nhập 0 đ</b><small>${items.slice(0,8).map(item=>`${esc(item.sku)} (${number(item.quantity)})`).join(' · ')}${items.length>8?' …':''}</small></div><p id="sapoReceiptStatus" role="status"></p><div class="dialog-actions"><button class="btn ghost" type="button" data-receipt-close>Hủy</button><button class="btn primary" type="submit">Xác nhận tạo đơn nhập Sapo</button></div></form></div>`;const close=()=>{closeModal('sapoReceipt');openModal('incomingStock');};receiptModal.querySelectorAll('[data-receipt-close]').forEach(button=>button.onclick=close);receiptModal.querySelector('form').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]'),status=form.querySelector('#sapoReceiptStatus'),payload={action:'create_purchase_receipt',ticket_number:form.elements.ticketNumber.value.trim(),supplier_name:form.elements.supplierName.value.trim(),warehouse_name:form.elements.warehouseName.value,employee_name:form.elements.employeeName.value,receipt_date:form.elements.receiptDate.value,total_quantity:total,items};button.disabled=true;status.textContent='Đang tạo phiếu nhập trên Sapo…';try{const result=await BN.api('/sapo-goods-receipt','POST',payload);status.innerHTML=result.sapoReceiptUrl?`<a href="${esc(result.sapoReceiptUrl)}" target="_blank" rel="noopener noreferrer">${esc(result.message)} · ${esc(result.sapoReceiptCode||'Mở phiếu trên Sapo')}</a>`:esc(result.message);button.textContent='Đã tạo đơn nhập';toast('Đã tạo phiếu nhập Sapo.');}catch(error){status.textContent=error.message;button.disabled=false;}};closeModal('incomingStock');openModal('sapoReceipt');}
 // Sapo owns the canonical spelling of suppliers and employees. The list is loaded
