   if(busy)return;
   const editRows=[...box.querySelectorAll('[data-edit-rows] tr')],payload={id:shipment.id,revision:shipment.updatedAt||shipment.createdAt,filename:shipment.filename||'',ticketNumber:box.querySelector('[data-edit-ticket]').value.trim(),warehouse:box.querySelector('[data-edit-warehouse]').value,arrivalDate:box.querySelector('[data-edit-date]').value,allowDuplicateRows:editRows.some(tr=>{const key=tr.querySelector('[data-sku]').value.trim().toLowerCase();return key&&tr.dataset.duplicateSkuApproved===key;}),rows:editRows.map(tr=>({sku:tr.querySelector('[data-sku]').value.trim(),quantity:Number(tr.querySelector('[data-qty]').value)}))};
