 async function exportPdf(shipment){
  if(!globalThis.PDFLib||!globalThis.fontkit)throw Error('Chưa tải được bộ xuất PDF. Vui lòng tải lại trang.');
  const fetchBytes=async url=>{const response=await fetch(url);if(!response.ok)throw Error('Không tải được font PDF.');return response.arrayBuffer();};
  const pdf=await PDFLib.PDFDocument.create();pdf.registerFontkit(globalThis.fontkit);
  const [regular,bold]=await Promise.all([pdf.embedFont(await fetchBytes('/fonts/TimesNewRoman.ttf'),{subset:true}),pdf.embedFont(await fetchBytes('/fonts/TimesNewRomanBold.ttf'),{subset:true})]);
  const pageSize=[595.28,841.89],margin=30,widths=[50,205,50,36,42,38,50,48];let page,y;
  const drawText=(text,x,top,size,font=regular,color=PDFLib.rgb(.06,.12,.22))=>page.drawText(String(text||''),{x,y:top-size,size,font,color});
  const lines=(text,font,size,width)=>{if(text==='')return [''];const result=[];let line='';String(text||'—').split(/\s+/).forEach(word=>{const next=line?line+' '+word:word;if(font.widthOfTextAtSize(next,size)<=width)line=next;else{if(line)result.push(line);line=word;}});if(line)result.push(line);return result.length?result:['—'];};
  const tableHeader=()=>{const headers=['SKU','SẢN PHẨM','THỰC NHẬN','SL','SP/THÙNG','THÙNG','KG','M³'];let x=margin;headers.forEach((header,index)=>{page.drawRectangle({x,y:y-18,width:widths[index],height:18,color:PDFLib.rgb(.9,.94,.98),borderColor:PDFLib.rgb(.45,.52,.61),borderWidth:.45});const textLines=lines(header,bold,6.3,widths[index]-5);textLines.forEach((line,lineIndex)=>drawText(line,x+3,y-5-lineIndex*7,6.3,bold));x+=widths[index];});y-=18;};
  const addPage=()=>{page=pdf.addPage(pageSize);y=806;drawText('PHIẾU HÀNG SẮP VỀ',margin,y,16,bold,PDFLib.rgb(.02,.16,.35));y-=24;drawText(`Số phiếu: ${shipment.ticketNumber||'Chưa có số phiếu'}`,margin,y,9,bold);drawText(`Kho nhận: ${shipment.warehouse||'—'}`,300,y,9,bold);y-=15;drawText(`Ngày về dự kiến: ${formatDate(shipment.arrivalDate)}`,margin,y,9);drawText(`Tổng: ${number(shipment.cartons)} thùng · ${number(shipment.weightKg)} kg · ${number(shipment.volumeM3)} m³`,300,y,9);y-=18;tableHeader();};
  addPage();
  shipment.rows.forEach(item=>{const values=[item.sku,item.name,'',number(item.quantity),display(item.perCarton),display(item.cartons),display(item.weightKg),display(item.volumeM3)],nameLines=lines(values[1],regular,7.2,widths[1]-6),height=Math.max(22,nameLines.length*9+7);if(y-height<35)addPage();let x=margin;values.forEach((value,index)=>{page.drawRectangle({x,y:y-height,width:widths[index],height,borderColor:PDFLib.rgb(.45,.52,.61),borderWidth:.4});const cellLines=index===1?nameLines:lines(value,regular,7.2,widths[index]-5);cellLines.forEach((line,lineIndex)=>drawText(line,x+3,y-5-lineIndex*9,7.2,index===1?regular:(index===0?regular:bold)));x+=widths[index];});y-=height;});
  const pages=pdf.getPages();pages.forEach((documentPage,index)=>documentPage.drawText(`Trang ${index+1} / ${pages.length}`,{x:pageSize[0]-88,y:16,size:8,font:regular,color:PDFLib.rgb(.28,.34,.42)}));
  const bytes=await pdf.save(),url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),link=document.createElement('a');link.href=url;link.download=`Phieu-hang-sap-ve-${String(shipment.ticketNumber||'chua-co-so').replace(/[\\/:*?"<>|]/g,'-')}-${shipment.arrivalDate||''}.pdf`;await (await import('/r2-export.js')).saveExport(await (await fetch(url)).blob(),link.download);link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
