 $('#incomingReview').onclick=async()=>{invalidate();lock(true);try{
  const sku=Number($('#incomingSku').value),quantity=Number($('#incomingQuantity').value),arrivalDate=$('#incomingDate').value,ticketNumber=$('#incomingTicket').value.trim();
  if(!Number.isInteger(sku)||!Number.isInteger(quantity)||sku===quantity)throw Error('Chọn riêng cột mã SKU và số lượng.');
  if(!ticketNumber)throw Error('Nhập số phiếu.');
  if(!arrivalDate)throw Error('Chọn ngày về hàng.');
  const values=[],seen=new Set();
  for(let index=Number($('#incomingHeader').value);index<rows.length;index++){
   const row=rows[index],code=String(row?.[sku]??'').trim(),amount=row?.[quantity];
   if(!code&&(amount===null||amount===undefined||String(amount).trim()===''))continue;
   if(!code)throw Error(`Dòng ${index+1}: thiếu mã SKU.`);
   if(seen.has(code.toLowerCase()))throw Error(`Dòng ${index+1}: SKU ${code} bị lặp.`);
   seen.add(code.toLowerCase());const value=Number(amount);
   if(!Number.isFinite(value)||value<0)throw Error(`Dòng ${index+1}: số lượng không hợp lệ.`);
   values.push({sku:code,quantity:value});
  }
  const file=$('#incomingFile').files[0],payload={rows:values,ticketNumber,warehouse:$('#incomingWarehouse').value,arrivalDate,filename:file?.name||'Phieu-giao-hang-OCR'};
  const result=await BN.api('/incoming-stock/preview','POST',payload);previewPayload=payload;
  $('#incomingStatus').textContent=`${result.matched.toLocaleString('vi-VN')} SKU hợp lệ · ${result.quantity.toLocaleString('vi-VN')} sản phẩm · ${number(result.cartons)} thùng · ${number(result.weightKg)} kg · ${number(result.volumeM3)} m³.`;
  $('#incomingPreview').innerHTML=`<p><b>Đối chiếu 20 SKU đầu:</b></p><div style="overflow:auto"><table style="min-width:680px"><thead><tr><th>SKU</th><th>Sản phẩm</th><th>SL</th><th>Thùng</th><th>Kg</th><th>m³</th></tr></thead><tbody>${result.samples.map(item=>`<tr><td>${esc(item.sku)}</td><td>${esc(item.name)}</td><td>${number(item.quantity)}</td><td>${item.cartons??'—'}</td><td>${item.weightKg===null?'—':number(item.weightKg)}</td><td>${item.volumeM3===null?'—':number(item.volumeM3)}</td></tr>`).join('')}</tbody></table></div>${result.unknown.length?`<details><summary>SKU không tìm thấy</summary><p>${result.unknown.map(esc).join(', ')}</p></details>`:''}`;
 }catch(error){$('#incomingStatus').textContent=error.message;}finally{lock(false);}};
